module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic in,
    output logic out
);

    typedef enum logic [0:0] {
        A = 1'b0,
        B = 1'b1
    } state_t;

    state_t state, next_state;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= B;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        case (state)
            B: begin
                if (in == 1'b0) next_state = A;
                else            next_state = B;
            end
            A: begin
                if (in == 1'b0) next_state = B;
                else            next_state = A;
            end
            default: next_state = B;
        endcase
    end

    // Moore machine output depends only on state
    always_comb begin
        case (state)
            B: out = 1'b1;
            A: out = 1'b0;
            default: out = 1'b1;
        endcase
    end

endmodule

