module tb_TopModule;
    logic clk;
    logic areset;
    logic in;
    logic out;

    TopModule uut (
        .clk(clk),
        .areset(areset),
        .in(in),
        .out(out)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        in = 0;
        #12;
        if (out !== 1'b1) begin
            $display("SELFTEST FAIL: Reset state should be B (out=1), got out=%b", out);
            $finish;
        end

        areset = 0;
        // Current state B (out=1)
        // B --0--> A
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 1'b0) begin
            $display("SELFTEST FAIL: Transition from B with in=0 should go to A (out=0), got %b", out);
            $finish;
        end

        // Current state A (out=0)
        // A --1--> A
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 1'b0) begin
            $display("SELFTEST FAIL: Transition from A with in=1 should stay A (out=0), got %b", out);
            $finish;
        end

        // Current state A (out=0)
        // A --0--> B
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            $display("SELFTEST FAIL: Transition from A with in=0 should go to B (out=1), got %b", out);
            $finish;
        end

        // Current state B (out=1)
        // B --1--> B
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            $display("SELFTEST FAIL: Transition from B with in=1 should stay B (out=1), got %b", out);
            $finish;
        end

        // Test asynchronous reset
        areset = 1;
        #2;
        if (out !== 1'b1) begin
            $display("SELFTEST FAIL: Asynchronous reset should set state to B (out=1) immediately, got %b", out);
            $finish;
        end
        areset = 0;

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
